/** Generate the electron-builder CJS config entrypoints from typed ESM source.
 * electron-builder itself only loads CommonJS; the generated files live in the
 * ignored apps/desktop/.generated/ directory and are rebuilt before packaging. */
import {mkdir, rm} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {build} from 'esbuild';

const desktop = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const GENERATED_DIRECTORY = path.join(desktop, '.generated');
export interface GeneratedBuilderConfig {
  readonly channel: 'production' | 'development';
  readonly file: string;
}
export const GENERATED_BUILDER_CONFIGS: readonly GeneratedBuilderConfig[] = Object.freeze([
  {channel: 'production', file: 'electron-builder.cjs'},
  {channel: 'development', file: 'electron-builder.dev.cjs'},
]);

/** Bundle the typed builder-config module into fixed CJS files. Only the fixed
 * channel literals below are compiled in; no caller-provided channel string or
 * arbitrary module path can reach electron-builder. */
export async function prepareBuilderConfig(directory: string = desktop): Promise<string[]> {
  const output = path.join(directory, '.generated');
  const entry = path.join(directory, 'builder-config.ts');
  // Preserve the source module's own location so resources resolve beside it,
  // not inside the generated directory.
  const sourceUrl = pathToFileURL(entry).href;
  await rm(output, {recursive: true, force: true});
  await mkdir(output, {recursive: true});
  const written: string[] = [];
  for (const specification of GENERATED_BUILDER_CONFIGS) {
    const outfile = path.join(output, specification.file);
    await build({
      stdin: {
        contents: `import {builderConfig} from './builder-config.ts';\nmodule.exports = builderConfig(${JSON.stringify(specification.channel)});\n`,
        resolveDir: directory,
        sourcefile: `prepare-builder-config-${specification.channel}.ts`,
        loader: 'ts',
      },
      outfile,
      bundle: true,
      platform: 'node',
      format: 'cjs',
      target: 'node24',
      define: {'import.meta.url': JSON.stringify(sourceUrl)},
      banner: {js: '// Generated by apps/desktop/scripts/prepare-builder-config.ts. Do not edit.'},
      sourcemap: false,
      legalComments: 'eof',
      logLevel: 'silent',
    });
    written.push(outfile);
  }
  return written;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const written = await prepareBuilderConfig();
  console.log(JSON.stringify({generated: written.map(file => path.relative(process.cwd(), file))}, null, 2));
}
